function portalThreats(){const live=projectiles.filter(p=>p.life>0&&(p.player||p.owner==='siege-walker')).map(p=>({id:p.id,alive:true,position:p.mesh.position,velocity:p.dir.clone().multiplyScalar(p.speed),speed:p.speed,owner:p.owner,blastRadius:3.8}));for(const m of robotMissiles?.missiles||[])if(m.alive)live.push({id:m.id,alive:true,position:m.position,velocity:m.velocity,speed:m.speed,owner:'siege-walker',target:m.target,homing:true,lockLost:!!m.lockLost,age:m.age,blastRadius:3.8});for(const b of evacuation?.raider?.bolts||[])live.push({id:b.id,alive:b.life>0,position:b.mesh.position,velocity:b.dir.clone().multiplyScalar(12),speed:12,owner:'evac-raider',blastRadius:0});live.push(...(plasmaArtillery?.threats()||[]));return live;}
function portalExitClear(p,unit){const radius=unit.kind==='tank'?2.8:.85;if(layout.buildings.some(b=>Math.abs(p.x-b.x)<5.2+radius&&Math.abs(p.z-b.z)<5.2+radius))return false;const center={x:p.x,y:p.y+(unit.kind==='tank'?1.1:1),z:p.z};if(traceImpact(center,center,{sections:physics.chunks,targets:unitDamage.units.filter(u=>u.alive&&u!==unit),radius,ground:false}))return false;for(const t of portalThreats()){if(t.impactPoint){if(Math.hypot(p.x-t.impactPoint.x,p.z-t.impactPoint.z)<t.blastRadius+radius+1)return false;continue;}const end={x:t.position.x+t.velocity.x*2,y:t.position.y+t.velocity.y*2,z:t.position.z+t.velocity.z*2};if(segmentBoxFraction(t.position,end,center,{x:radius+3,y:2,z:radius+3})!==null)return false;}return true;}
