function artilleryCamera(){const points=[robot.root.position.clone().add(new THREE.Vector3(0,12,0))];for(const s of plasmaArtillery?.shells||[]){points.push(new THREE.Vector3(s.target.x,1,s.target.z));points.push(new THREE.Vector3(s.target.x,Math.max(25,s.trajectory.apex),s.target.z));}if(points.length===1){const p=plasmaArtillery?.history.at(-1)?.planned||{x:-36,y:.08,z:0};points.push(new THREE.Vector3(p.x,1,p.z));}const box=new THREE.Box3().setFromPoints(points),target=box.getCenter(new THREE.Vector3()),radius=Math.max(20,box.getSize(new THREE.Vector3()).length()*.5),fov=Math.min(THREE.MathUtils.degToRad(camera.fov),2*Math.atan(Math.tan(THREE.MathUtils.degToRad(camera.fov)/2)*camera.aspect)),distance=radius/Math.sin(fov/2)*1.1,offset=new THREE.Vector3(.35,.85,.65).normalize().multiplyScalar(distance);return{target,position:target.clone().add(offset)};}
function setView(name){const selected={hero:'violet',runner:'volt',portal:'rift',solara:'solara',mochi:'mochi'}[name];if(selected&&!roster.has(selected))return;if(runner?.active)runner.exit();if(pilot?.active)pilot.exit();view=name;document.querySelector('.viewer').classList.toggle('is-solara-view',name==='solara');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));const narrow=camera.aspect<.85;if(name==='overview'){camera.position.set(narrow?112:77,narrow?100:68,narrow?125:85);controls.target.set(0,6,0);}if(name==='hero'&&hero){const pose=heroCamera();camera.position.copy(pose.position);controls.target.copy(pose.target);}if(name==='runner'&&runner){const pose=runnerEscortCamera();camera.position.copy(pose.position);controls.target.copy(pose.target);}if(name==='solara'&&solara){const pose=solaraCamera();camera.position.copy(pose.position);controls.target.copy(pose.target);}if(name==='mochi'&&mochi){camera.position.copy(mochi.root.position).add(new THREE.Vector3(6,3,7));controls.target.copy(mochi.root.position).add(new THREE.Vector3(0,1.2,0));}if(name==='portal'&&portalHero){const pose=portalCamera();camera.position.copy(pose.position);controls.target.copy(pose.target);}if(name==='artillery'&&plasmaArtillery){const pose=artilleryCamera();camera.position.copy(pose.position);controls.target.copy(pose.target);}if(name==='robot'){camera.position.copy(robot.root.position).add(new THREE.Vector3(-30,21,4));controls.target.copy(robot.root.position).add(new THREE.Vector3(0,11,0));}if(name==='street'){camera.position.set(-47,4.5,6.5);controls.target.set(-7,2.4,0);}if(name==='tank'&&tanks[0]){camera.position.copy(tanks[0].root.position).add(new THREE.Vector3(-9,6,10));controls.target.copy(tanks[0].root.position).add(new THREE.Vector3(3,1,0));}if(name==='air'&&helicopters[0]){camera.position.copy(helicopters[0].root.position).add(new THREE.Vector3(10,5,14));controls.target.copy(helicopters[0].root.position);}if(name==='infantry'&&soldierCrowd){const p=soldierCrowd.position();camera.position.copy(p).add(new THREE.Vector3(3.5,2.1,3.0));controls.target.copy(p).add(new THREE.Vector3(0,1.05,0));}controls.update();$('camera-label').textContent={overview:'OBSERVER / FREE ORBIT',artillery:'TRACKING / PLASMA ARTILLERY',robot:'TRACKING / SIEGE WALKER',hero:'TRACKING / VIOLET SENTINEL',solara:'TRACKING / SOLARA FROST',mochi:'TRACKING / MOCHI PINK',portal:'TRACKING / RIFT WARDEN',runner:'TRACKING / VOLT RUSH — CPU',street:'OBSERVER / STREET LEVEL',tank:'TRACKING / NORTH ARMOR',air:'TRACKING / NORTH ROTORCRAFT',infantry:'TRACKING / NORTH RIFLEMAN'}[name]||'OBSERVER / FREE ORBIT';}
